def run():
    print("module check: %s" % idc.get_name(0x10004670))
    IDB = 0x10000000
    rec_named, own_named, skipped = 0, 0, 0
    for off, name in ROWS:
        ea = IDB + off
        cur = idc.get_name(ea) or ""
        if cur.startswith("dword_") or cur.startswith("off_") or cur.startswith("byte_") or cur == "":
            if ida_name.set_name(ea, "g_cvar_" + name, ida_name.SN_NOWARN | ida_name.SN_FORCE):
                rec_named += 1
        else:
            skipped += 1
        idc.set_cmt(ea, "Cached LTConVar* for console variable '%s'.\n"
                        "The record's first field IS the float the engine reads, so a four-byte store here\n"
                        "changes the setting with no lookup and no engine call. One of 474 such pairs in\n"
                        "gameclient .data; read via sdk::Engine::find_cached_var(\"%s\")." % (name, name), 1)
        oea = ea + 4
        ocur = idc.get_name(oea) or ""
        if ocur.startswith("dword_") or ocur.startswith("off_") or ocur == "":
            if ida_name.set_name(oea, "g_cvarOwner_" + name, ida_name.SN_NOWARN | ida_name.SN_FORCE):
                own_named += 1
        idc.set_cmt(oea, "ILTClient this cached variable was resolved through; all 474 pairs share it.", 1)
    print("record globals named %d, owner globals named %d, already-named skipped %d (of %d)"
          % (rec_named, own_named, skipped, len(ROWS)))
    for ea in (0x101F69E0, 0x101FFBC8, 0x101F936C):
        print("  0x%08X -> %s" % (ea, idc.get_name(ea)))
run()
